import arrow

def test_dehumanize_locales():
    now = arrow.utcnow()
    locales_to_test = ["fi", "fi-fi", "ne", "ne-np", "ee", "et", "zu", "zu-za"]

    for loc in locales_to_test:
        try:
            # We don't care about the result, just that it doesn't raise ValueError
            now.dehumanize("2 days ago", locale=loc)
            print(f"Locale {loc} is supported")
        except ValueError as e:
            print(f"Locale {loc} is NOT supported: {e}")
            raise e

if __name__ == "__main__":
    test_dehumanize_locales()

